from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy
import itertools

class MaxMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    # Helper: Build adjacency dict from edge list
    @staticmethod
    def build_adj_dict(nodes, edges):
        adj = {n: set() for n in nodes}
        for u,v in edges:
            adj[u].add(v)
            adj[v].add(u)
        return adj

    # Bron-Kerbosch algorithm to enumerate maximal independent sets
    @staticmethod
    def enumerate_maximal_independent_sets(nodes, adj):
        maximal_sets = []
        nodelist = list(nodes)
        # For Bron–Kerbosch, complement the adjacency to get co-graph (for cliques), or customize
        def bronkkerbosch2(R, P, X):
            if not P and not X:
                maximal_sets.append(R)
                return
            for v in list(P):
                # N(v) are neighbors of v, so nodes that cannot be added
                Nv = adj[v]
                bronkkerbosch2(R | {v}, P - Nv - {v}, X - Nv - {v})
                P = P - {v}
                X = X | {v}
        bronkkerbosch2(set(), set(nodelist), set())
        return maximal_sets

    # Counts maximal independent sets
    @staticmethod
    def count_maximal_independent_sets(nodes, edges):
        adj = MaxMaximalCocktailsCustomStrategy.build_adj_dict(nodes, edges)
        return len(MaxMaximalCocktailsCustomStrategy.enumerate_maximal_independent_sets(nodes, adj))

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list = data['nodes']
        edges_list = data['edges']
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']
        new_edge = None

        nodes_set = set(nodes_list)
        existing_edges = set()
        for u,v in edges_list:
            if u > v:
                u,v = v,u
            existing_edges.add((u,v))

        # Generate all possible pairs (u,v) (u < v) that are not yet edges
        candidates = []
        for u,v in itertools.combinations(nodes_list, 2):
            if (u,v) not in existing_edges:
                candidates.append( (u,v) )
        if not candidates:
            # No move possible
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )
        # Efficient: compute adj dict once
        adj = self.build_adj_dict(nodes_list, edges_list)
        # Early: If graph is large (n>13), approximate by picking a random legal edge between most unconnected nodes
        n = len(nodes_list)
        check_all = n <= 13
        if check_all:
            # For each edge, add it, and check if cnt_maximal_cocktails does not decrease
            for u,v in candidates:
                # Simulate adding edge (u,v)
                new_edges = list(edges_list) + [(u,v)]
                cnt2 = self.count_maximal_independent_sets(nodes_list, new_edges)
                if cnt2 >= cnt_maximal_cocktails:
                    new_edge = (u,v)
                    break
        else:
            # Approximate: choose a pair of highest degree nodes not already connected, but check legality!
            # Degree count
            deg = {x: len(adj[x]) for x in nodes_set}
            sorted_nodes = sorted(nodes_list, key=lambda x: -deg[x])
            found = False
            for u in sorted_nodes:
                for v in sorted_nodes:
                    if u < v and (u,v) not in existing_edges:
                        # Simulate addition, but only enumerate up to 20000 sets
                        approx_sets = self.enumerate_maximal_independent_sets_approx(nodes_list, list(edges_list)+[(u,v)], upper=20000)
                        cnt2 = len(approx_sets)
                        if cnt2 >= cnt_maximal_cocktails:
                            new_edge = (u,v)
                            found = True
                            break
                if found:
                    break
            if new_edge is None:
                # fallback: pick any available legal move (should not occur unless all lose)
                new_edge = candidates[0]
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=new_edge, type='custom')]
        )
    # For large graphs, approximate by truncating the recursion
    @staticmethod
    def enumerate_maximal_independent_sets_approx(nodes, edges, upper=20000):
        maximal_sets = []
        adj = MaxMaximalCocktailsCustomStrategy.build_adj_dict(nodes, edges)
        nodelist = list(nodes)
        def bronkkerbosch2(R, P, X):
            if len(maximal_sets) >= upper:
                return
            if not P and not X:
                maximal_sets.append(R)
                return
            for v in list(P):
                Nv = adj[v]
                bronkkerbosch2(R | {v}, P - Nv - {v}, X - Nv - {v})
                P = P - {v}
                X = X | {v}
        bronkkerbosch2(set(), set(nodelist), set())
        return maximal_sets

