from pydantic import BaseModel  
from typing import List, Optional, Dict, Any, Set, Tuple  
from enum import Enum  
from abc import abstractmethod  

from system.message import Info  
from system.message import BaseMessageDataType  
from model.strategy_type import StrategyType  
from model.base import BaseStrategy  

class MaxMaximalCocktailsCustomStrategy:  
    def __init__(self, model: BaseStrategy):  
        self._model = model  
        self.name = self._model.name  
        self.history = self._model.history  
        self.strategy_type = StrategyType.SMT  

    def update_model_field(self, field_name: str, value: Any):  
        if hasattr(self._model, field_name):  
            setattr(self._model, field_name, value)  

    def receive_message(self, message: Info) -> Info:  
        data = message.message[0].data  
        nodes_list: List[int] = data['nodes']  
        edges_list: List[Tuple[int, int]] = data['edges']  
        cnt_maximal_cocktails: int = data['cnt_maximal_cocktails']  

        # Build adjacency
        N = len(nodes_list)
        node_to_idx = {node: i for i, node in enumerate(nodes_list)}
        idx_to_node = {i: node for i, node in enumerate(nodes_list)}
        adj = [set() for _ in range(N)]
        for u, v in edges_list:
            ui, vi = node_to_idx[u], node_to_idx[v]
            adj[ui].add(vi)
            adj[vi].add(ui)

        # Bron–Kerbosch algorithm without pivoting for maximal independent sets
        def bron_kerbosch(R: Set[int], P: Set[int], X: Set[int], out: List[Set[int]]):
            if not P and not X:
                out.append(R.copy())  # found maximal
                return
            for v in list(P):
                bron_kerbosch(R | {v}, P - adj[v] - {v}, X - adj[v] - {v}, out)
                P.remove(v)
                X.add(v)

        # Enumerate all maximal independent sets as sets of node indices
        maximal_ind_sets: List[Set[int]] = []
        bron_kerbosch(set(), set(range(N)), set(), maximal_ind_sets)
        # For lookup, make a set of frozensets
        MIS_containing = dict()    # (u, v) -> True if any MIS contains both
        for S in maximal_ind_sets:
            for u in S:
                for v in S:
                    if u < v:
                        MIS_containing.setdefault((u, v), True)
        # Try all possible edges
        found_legal = False
        new_edge = None
        for i in range(N):
            for j in range(i+1, N):
                if j not in adj[i]:
                    # If no maximal independent set contains both, adding (i, j) is legal
                    if not MIS_containing.get((i, j), False):
                        # Return first legal edge (lex smallest)
                        new_edge = (idx_to_node[i], idx_to_node[j])
                        found_legal = True
                        break
            if found_legal:
                break
        # Fail safe: if all additions reduce count, return None (shouldn't happen)
        # Return edge or None
        return Info(
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
            message=[BaseMessageDataType(data=new_edge, type='custom')]  
        )

