from pydantic import BaseModel  
from typing import List, Optional, Dict, Any  
from enum import Enum  
from abc import abstractmethod  

from system.message import Info  
from system.message import BaseMessageDataType  
from model.strategy_type import StrategyType  
from model.base import BaseStrategy  
import itertools  
import random

# Helper - enumerate all maximal independent sets (Bron–Kerbosch without pivoting, for small n)
def maximal_independent_sets(adj_dict, nodes):
    all_sets = []
    n = len(nodes)
    node_idx = {node: idx for idx, node in enumerate(nodes)}
    neighbors = {node: set(adj_dict[node]) for node in nodes}
    # Each set is a candidate, test maximality and independence
    for r in range(1, n+1):
        for subset in itertools.combinations(nodes, r):
            subset_set = set(subset)
            # independence: no two nodes share an edge
            flag = True
            for u in subset:
                if neighbors[u] & subset_set:
                    flag = False
                    break
            if not flag:
                continue
            # maximality: for every node not in subset, adding it gives a non-indep set
            maximal = True
            for u in nodes:
                if u in subset_set:
                    continue
                if all(u not in neighbors[v] for v in subset_set):
                    maximal = False
                    break
            if maximal:
                all_sets.append(frozenset(subset_set))
    return set(all_sets)

# Fast path for larger n: pick two nodes of degree zero

def find_legal_edge(nodes, edges, cnt_maximal_cocktails):
    n = len(nodes)
    edge_set = set(tuple(sorted(e)) for e in edges)
    # build adjacency list
    adj = {u: set() for u in nodes}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    all_possible_edges = []
    for i in range(n):
        for j in range(i+1, n):
            u, v = nodes[i], nodes[j]
            if (u, v) not in edge_set:
                all_possible_edges.append( (u,v) )
    # For small graphs, check strictly
    if n <= 8:
        # Compute all MIS of current graph
        orig_MIS = maximal_independent_sets(adj, nodes)
        cnt0 = len(orig_MIS)
        for (u, v) in all_possible_edges:
            # add the edge
            adj2 = {k: set(adj[k]) for k in adj}
            adj2[u].add(v)
            adj2[v].add(u)
            new_MIS = maximal_independent_sets(adj2, nodes)
            cnt1 = len(new_MIS)
            if cnt1 >= cnt0:
                return (u, v)
    else:
        # For larger graphs, try to find two nodes with degree 0
        zero_deg = [u for u in nodes if len(adj[u])==0]
        if len(zero_deg)>=2:
            return (zero_deg[0], zero_deg[1])
        # Else, pick random non-edge (likely safe for big n)
        for (u, v) in all_possible_edges:
            # avoid creating K_2 connected to all others (not a unique cocktail)
            if len(adj[u])<n-2 and len(adj[v])<n-2:
                return (u, v)
        # else fallback
        return all_possible_edges[0]
    # If all else fails
    return all_possible_edges[0]

class MaxMaximalCocktailsCustomStrategy:  
    def __init__(self, model: BaseStrategy):  
        self._model = model  
        self.name = self._model.name  
        self.history = self._model.history  
        self.strategy_type = StrategyType.SMT  

    def update_model_field(self, field_name: str, value: Any):  
        if hasattr(self._model, field_name):  
            setattr(self._model, field_name, value)  

    def receive_message(self, message: Info) -> Info:  
        data = message.message[0].data  
        nodes_list = data['nodes']  
        edges_list = data['edges']  
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']  

        new_edge = find_legal_edge(nodes_list, edges_list, cnt_maximal_cocktails)  
        return Info(  
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
            message=[BaseMessageDataType(data=new_edge, type='custom')]  
        )

