        # For small graphs (N <= 8), brute-force is ok
        nodes = list(G.nodes())
        n = len(nodes)
        maximal_sets = set()
        # Generate all subsets, test each for independence and maximality
        for r in range(1, n+1):
            for subset in itertools.combinations(nodes, r):
                s = set(subset)
                # Check independence
                independent = True
                for u, v in itertools.combinations(s, 2):
                    if G.has_edge(u, v):
                        independent = False
                        break
                if not independent:
                    continue
                # Maximal: for every node not in s, adding it breaks independence
