        for i in range(n):
            for j in range(i+1, n):
                u = nodes_list[i]
                v = nodes_list[j]
                if tuple(sorted((u,v))) not in edge_set:
                    all_node_pairs.append( (u,v) )

        # Try each candidate edge, only propose one that preserves or increases the #maximal cocktails
        import random
        random.shuffle(all_node_pairs)  # For tie-breaking/fairness
        found = False
        for (u, v) in all_node_pairs:
            # Copy adjacency
            new_adj = {x: set(adj[x]) for x in adj}
            new_adj[u].add(v)
            new_adj[v].add(u)
            try:
                new_cnt = count_maximal_independent_sets(new_adj)
            except Exception as ex:
                # Catch any overflow or runaway recursion, fallback strategy described below
                new_cnt = -1
            if new_cnt >= cnt_maximal_cocktails:
                new_edge = (u, v)
                found = True
